import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const p=JSON.parse('{"title":"桌面应用（nekcode GUI）","description":"","frontmatter":{},"headers":[],"relativePath":"gui/index.md","filePath":"gui/index.md"}'),n={name:"gui/index.md"};function r(l,e,c,i,s,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="桌面应用-nekcode-gui" tabindex="-1">桌面应用（nekcode GUI） <a class="header-anchor" href="#桌面应用-nekcode-gui" aria-label="Permalink to &quot;桌面应用（nekcode GUI）&quot;">​</a></h1><p>nekcode GUI 是 nek 的图形界面。它和终端里的 <code>nek</code> 是<strong>同一个 nek 的两种用法</strong>，就像 Codex app 和 Codex CLI：两边读同一组配置文件，用同一份模型列表、同样的 Skill 和 MCP 服务器，会话也存在同一个地方。在一边改了配置，另一边下次读取时就能看到，不需要同步，也没有“GUI 专用”的第二份配置。</p><p>源码和安装包在 <a href="https://github.com/deepdarkpaw/nekcode-gui" target="_blank" rel="noreferrer">deepdarkpaw/nekcode-gui</a>。</p><h2 id="shared" tabindex="-1">与 CLI 共用什么 <a class="header-anchor" href="#shared" aria-label="Permalink to &quot;与 CLI 共用什么 {#shared}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>位置</th><th>GUI 里的入口</th></tr></thead><tbody><tr><td>服务商与模型</td><td><code>~/.nek/agent/models.json</code></td><td>设置 → 服务商</td></tr><tr><td>默认模型、思考等级、循环范围</td><td><code>~/.nek/agent/settings.json</code>（项目里是 <code>.nek/settings.json</code>）</td><td>设置 → 默认模型</td></tr><tr><td>认证信息</td><td><code>~/.nek/agent/auth.json</code></td><td>设置 → 服务商</td></tr><tr><td>Skill</td><td><code>~/.nek/agent/skills/</code>、项目里的 <code>.nek/skills/</code></td><td>设置 → 技能 / 命令；输入框里的 <code>/</code></td></tr><tr><td>提示词模板</td><td><code>~/.nek/agent/prompts/</code>、项目里的 <code>.nek/prompts/</code></td><td>设置 → 技能 / 命令；输入框里的 <code>/</code></td></tr><tr><td>MCP 服务器</td><td><code>~/.nek/agent/mcp.json</code>、项目里的 <code>.nek/mcp.json</code></td><td>设置 → MCP</td></tr><tr><td>项目信任</td><td><code>~/.nek/agent/trust.json</code></td><td>首次打开项目时的确认</td></tr><tr><td>会话</td><td>nek 的会话目录（默认 <code>~/.nek/agent/sessions/</code>）</td><td>侧栏的对话列表</td></tr></tbody></table><p>各文件的含义见 <a href="/nekcode/customize/configuration">配置总览</a>。GUI 不会扫描 <code>~/.agents/skills</code> 等其他目录，Skill 的位置规则和 CLI 完全一样，见 <a href="/nekcode/customize/skills#locations">Skills</a>。</p><p>GUI 自己只保存界面数据（窗口布局、标签页、外观设置、日志等），放在 <code>~/.nek/gui/v2/</code>。在「设置 → 数据存储路径」里可以把这部分搬到别的磁盘，<code>.nek/gui/v2</code> 这段后缀不变；nek 的配置不受影响。</p><h2 id="install" tabindex="-1">安装与更新 <a class="header-anchor" href="#install" aria-label="Permalink to &quot;安装与更新 {#install}&quot;">​</a></h2><ol><li>先安装 nek（GUI 需要 <strong>0.5.1-beta.7 或更新版本</strong>），见 <a href="/nekcode/start/install">安装、更新与卸载</a>。没有装也可以直接启动 GUI，首次启动的引导里能一键安装。</li><li>到 <a href="https://github.com/deepdarkpaw/nekcode-gui/releases" target="_blank" rel="noreferrer">nekcode-gui Releases</a> 下载安装包：Intel/AMD 电脑选 <code>nekcode-&lt;版本&gt;-win-x64.exe</code>，ARM 电脑选 <code>win-arm64</code>。所有文件都可以用同页的 <code>SHA256SUMS</code> 校验。</li></ol><p>安装包没有代码签名，Windows 弹出 SmartScreen 时点「更多信息 → 仍要运行」。macOS 安装包目前不随每个 Beta 发布。</p><p>GUI 会自动检查自己的新版本，也可以在帮助菜单（右上角的 <code>?</code>）里点「检查更新」。nek 本身用 <code>nek update</code> 更新；更新前先关掉正在运行的 nek 会话，包括 GUI 里的会话。</p><h2 id="composer" tabindex="-1">输入框 <a class="header-anchor" href="#composer" aria-label="Permalink to &quot;输入框 {#composer}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>输入</th><th>作用</th></tr></thead><tbody><tr><td><code>/</code></td><td>斜杠命令、Skill 和提示词模板。这是使用 Skill 的唯一入口</td></tr><tr><td><code>@</code></td><td>引用工作区里的文件或目录，或点名一个 <a href="/nekcode/guide/subagents">子代理</a></td></tr></tbody></table><p>模型正在工作时继续输入，消息会排队等待，或作为引导插入当前一轮，与 CLI 的 <a href="/nekcode/guide/usage">排队消息</a> 相同。</p><h2 id="models" tabindex="-1">模型 <a class="header-anchor" href="#models" aria-label="Permalink to &quot;模型 {#models}&quot;">​</a></h2><p>「设置 → 服务商」里的模型表<strong>就是</strong> <code>models.json</code> 本身：在 GUI 里新增、批量导入、从服务商拉取或复制的模型，都写进这个文件，效果和在 CLI 那边手动编辑完全一样。改名或删除模型时，<code>enabledModels</code> 里明确指向它的条目会一起更新。</p><p>「设置 → 默认模型 → 循环范围」对应 CLI 的 <code>/scoped-models</code>，也就是 <code>settings.json</code> 里的 <code>enabledModels</code>：</p><ul><li><strong>不设置（默认）</strong>：GUI 的模型菜单和 CLI 的 <code>/model</code> 都显示全部已配置的模型。</li><li><strong>设置后</strong>：两边都默认只显示这些模型，循环切换也只在其中进行；模型菜单里可以切到「显示全部模型」。</li></ul><p>如果某个模型在 GUI 能看到、在 CLI 看不到（或反过来），先检查 <code>enabledModels</code> 是否限定了范围。详见 <a href="/nekcode/guide/models">选择模型</a>。</p><h2 id="plan" tabindex="-1">Plan 模式 <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan 模式 {#plan}&quot;">​</a></h2><p>把对话模式切到 Plan 后，nek 只调研和写计划，规则与 <a href="/nekcode/guide/plan-mode">Plan 模式</a> 相同。计划写好后，对话里会出现计划卡片：</p><ul><li>卡片和审批按钮保存在会话里，离开一段时间、切换对话或重启 GUI 后仍在；</li><li>只有当前修订版本可以执行，执行时等同于 <code>/nek-build &lt;计划ID&gt; --revision &lt;修订号&gt;</code>，计划在审阅后被改过时，nek 会拒绝执行并要求重新审阅；</li><li>不批准而直接发送新消息，等于放弃这次审批，旧卡片不会再重复出现。</li></ul><h2 id="help" tabindex="-1">帮助菜单 <a class="header-anchor" href="#help" aria-label="Permalink to &quot;帮助菜单 {#help}&quot;">​</a></h2><p>右上角的 <code>?</code> 菜单提供：</p><table tabindex="0"><thead><tr><th>项目</th><th>作用</th></tr></thead><tbody><tr><td>产品文档</td><td>打开本手册</td></tr><tr><td>导出日志</td><td>把 GUI 日志打包成 zip，反馈问题时附上</td></tr><tr><td>资源管理器</td><td>查看 GUI 相关进程的资源占用，以及数据目录的磁盘占用</td></tr><tr><td>检查更新</td><td>检查 GUI 新版本</td></tr><tr><td>关于 nekcode</td><td>版本信息</td></tr></tbody></table><h2 id="remote" tabindex="-1">远程开发 <a class="header-anchor" href="#remote" aria-label="Permalink to &quot;远程开发 {#remote}&quot;">​</a></h2><p>GUI 可以通过 SSH 连接 Linux 主机，在远端运行 nek，见 <a href="/nekcode/gui/remote">Remote SSH</a>。</p>',27)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
